(function () {
  function safeLog(message) {
    try {
      if (typeof ZT !== 'undefined' && ZT && typeof ZT.log === 'function') {
        ZT.log(message);
      }
    } catch (e) {}
  }

  function getRaw(name) {
    try {
      if (
        typeof formData !== 'undefined' &&
        formData &&
        formData[name] !== undefined &&
        formData[name] !== null
      ) {
        return formData[name];
      }
    } catch (e) {}

    try {
      if (typeof ZT !== 'undefined' && ZT && typeof ZT.getVariableValue === 'function') {
        var value = ZT.getVariableValue(name, '');
        if (value !== undefined && value !== null) {
          return value;
        }
      }
    } catch (e) {}

    try {
      if (typeof ZT !== 'undefined' && ZT && typeof ZT.getFormData === 'function') {
        var value2 = ZT.getFormData(name);
        if (value2 !== undefined && value2 !== null) {
          return value2;
        }
      }
    } catch (e) {}

    return '';
  }

  function saveOutput(name, value) {
    try {
      if (typeof formData !== 'undefined' && formData) {
        formData[name] = value;
      }
    } catch (e) {}

    try {
      if (typeof ZT !== 'undefined' && ZT && typeof ZT.setFormData === 'function') {
        ZT.setFormData(name, value);
      }
    } catch (e) {
      safeLog('Failed setFormData for ' + name + ': ' + e.message);
    }

    try {
      if (typeof ZT !== 'undefined' && ZT && typeof ZT.setTransformData === 'function') {
        ZT.setTransformData(name, value);
      }
    } catch (e) {
      safeLog('Failed setTransformData for ' + name + ': ' + e.message);
    }

    try {
      if (typeof ZT !== 'undefined' && ZT && typeof ZT.setVariableValue === 'function') {
        ZT.setVariableValue(name, value);
      }
    } catch (e) {
      safeLog('Failed setVariableValue for ' + name + ': ' + e.message);
    }
  }

  function pad2(value) {
    value = parseInt(value, 10);
    return value < 10 ? '0' + value : String(value);
  }

  function toSalesforceTime(value) {
    var raw = String(value || '').trim();

    if (!raw) {
      return '';
    }

    // Already Salesforce-friendly, e.g. 01:00:00.000Z
    if (/^\d{2}:\d{2}:\d{2}\.\d{3}Z$/.test(raw)) {
      return raw;
    }

    // 24-hour format, e.g. 13:30 or 13:30:00
    var twentyFourHourMatch = raw.match(/^([01]?\d|2[0-3]):([0-5]\d)(?::([0-5]\d))?$/);
    if (twentyFourHourMatch) {
      return (
        pad2(twentyFourHourMatch[1]) +
        ':' +
        pad2(twentyFourHourMatch[2]) +
        ':' +
        pad2(twentyFourHourMatch[3] || '0') +
        '.000Z'
      );
    }

    // 12-hour format, e.g. 1:00 AM, 12:15 PM
    var twelveHourMatch = raw.match(/^(\d{1,2}):([0-5]\d)\s*(AM|PM)$/i);
    if (twelveHourMatch) {
      var hour = parseInt(twelveHourMatch[1], 10);
      var minute = twelveHourMatch[2];
      var meridiem = twelveHourMatch[3].toUpperCase();

      if (hour < 1 || hour > 12) {
        return '';
      }

      if (meridiem === 'AM' && hour === 12) {
        hour = 0;
      } else if (meridiem === 'PM' && hour !== 12) {
        hour += 12;
      }

      return pad2(hour) + ':' + minute + ':00.000Z';
    }

    return '';
  }

  function convertAndSave(fieldName) {
    var originalValue = getRaw(fieldName);
    var convertedValue = toSalesforceTime(originalValue);

    if (convertedValue) {
      saveOutput(fieldName, convertedValue);
      saveOutput(fieldName + '_display', originalValue);
      safeLog(fieldName + ' converted from "' + originalValue + '" to "' + convertedValue + '"');
    } else {
      saveOutput(fieldName, '');
      saveOutput(fieldName + '_display', originalValue);
      safeLog(fieldName + ' could not be converted. Original value: "' + originalValue + '"');
    }
  }

  try {
    convertAndSave('sf_Collector_Arrival_Time_Actual__c');
    convertAndSave('sf_End_Time_Actual__c');
    convertAndSave('sf_BAT_Collection_Time_Actual__c');

    saveOutput('sf_time_conversion_status', 'success');
    saveOutput('sf_time_conversion_error', '');
  } catch (err) {
    var errorMessage = err && err.message ? err.message : String(err);

    saveOutput('sf_time_conversion_status', 'error');
    saveOutput('sf_time_conversion_error', errorMessage);

    safeLog('Salesforce time conversion script error: ' + errorMessage);
  }
})();
